const deleteExpiredReplies = `-- name: DeleteExpiredReplies :execrows
DELETE FROM thread_replies t
WHERE t.org_id = $1 AND t.id IN (SELECT r.id
                                  FROM thread_replies r
                                  WHERE r.org_id = $1 AND r.state IN ('sent', 'dropped', 'not_delivered')
                                    AND r.created_at < $2
                                  ORDER BY r.created_at, r.id
                                  LIMIT $3
                                  FOR UPDATE SKIP LOCKED)
`

type DeleteExpiredRepliesParams struct {
	OrgID     int64
	Cutoff    time.Time
	BatchSize int32
}

// DeleteExpiredReplies deletes at most @batch_size Thread replies that are sent, dropped or not delivered and were
// created before @cutoff, skipping rows another transaction holds.
func (q *Queries) DeleteExpiredReplies(ctx context.Context, arg DeleteExpiredRepliesParams) (int64, error) {
	result, err := q.db.Exec(ctx, deleteExpiredReplies, arg.OrgID, arg.Cutoff, arg.BatchSize)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

