const leaseOldestWaiting = `-- name: LeaseOldestWaiting :one
WITH oldest AS (
    SELECT x.id, (x.lease_until IS NULL OR x.lease_until <= $1::timestamptz) AS free
    FROM deliveries x
    WHERE x.org_id = $2 AND x.destination_id = $3 AND x.state = 'pending'
      AND x.held_by_storm_id IS NULL
    ORDER BY x.next_attempt_at, x.id
    LIMIT 1
    FOR UPDATE OF x
), leased AS (
    UPDATE deliveries d
    SET lease_owner      = $4::text,
        lease_until      = $5::timestamptz,
        publication_loud = CASE
                               WHEN d.published_at IS NULL AND d.alert_group_id IS NOT NULL
                                   THEN coalesce((SELECT g.status = 'firing'
                                                  FROM alert_groups g
                                                  WHERE g.org_id = d.org_id AND g.id = d.alert_group_id), false)
                               ELSE d.publication_loud
                           END,
        late_note        = CASE WHEN d.published_at IS NULL THEN false ELSE d.late_note END
    FROM oldest o
    WHERE d.org_id = $2 AND d.id = o.id AND o.free
    RETURNING d.id
)
SELECT o.id, o.free::boolean AS free
FROM oldest o
`

type LeaseOldestWaitingParams struct {
	Now           time.Time
	OrgID         int64
	DestinationID int64
	Owner         string
	LeaseUntil    time.Time
}

type LeaseOldestWaitingRow struct {
	ID   int64
	Free bool
}

// LeaseOldestWaiting is the probe's delivery: the oldest pending delivery of a Destination that no Storm holds, leased
// to this replica when its lease is free. No row when nothing waits; free is false when it is leased elsewhere. A
// first Publication of an Alert Group it leases follows the recovery rule: Loud only when the Alert Group is firing at
// that moment, and without the late note (C-11.FR-19).
func (q *Queries) LeaseOldestWaiting(ctx context.Context, arg LeaseOldestWaitingParams) (LeaseOldestWaitingRow, error) {
	row := q.db.QueryRow(ctx, leaseOldestWaiting,
		arg.Now,
		arg.OrgID,
		arg.DestinationID,
		arg.Owner,
		arg.LeaseUntil,
	)
	var i LeaseOldestWaitingRow
	err := row.Scan(&i.ID, &i.Free)
	return i, err
}

const leaseOldestWaitingEvent = `-- name: LeaseOldestWaitingEvent :one
WITH oldest AS (
    SELECT x.id, (x.lease_until IS NULL OR x.lease_until <= $1::timestamptz) AS free
    FROM webhook_events x
    WHERE x.org_id = $2 AND x.destination_id = $3 AND x.state = 'pending'
      AND NOT EXISTS (SELECT 1
                      FROM webhook_events p
                      WHERE p.org_id = x.org_id AND p.destination_id = x.destination_id
                        AND p.alert_group_id = x.alert_group_id AND p.state = 'pending' AND p.sequence < x.sequence)
    ORDER BY (x.next_attempt_at <= $4::timestamptz) DESC, x.id
    LIMIT 1
    FOR UPDATE OF x
), leased AS (
    UPDATE webhook_events e
    SET lease_owner = $5::text, lease_until = $6::timestamptz
    FROM oldest o
    WHERE e.org_id = $2 AND e.id = o.id AND o.free
    RETURNING e.id
)
SELECT o.id, o.free::boolean AS free
FROM oldest o
`

type LeaseOldestWaitingEventParams struct {
	Now           time.Time
	OrgID         int64
	DestinationID int64
	Due           time.Time
	Owner         string
	LeaseUntil    time.Time
}

type LeaseOldestWaitingEventRow struct {
	ID   int64
	Free bool
}

// LeaseOldestWaitingEvent is the probe's event: among the head events of the Destination's Alert Groups, the oldest
// one that is due at @due — so that a Retry-After is kept — else the oldest one, leased to this replica when its lease
// is free. No row when nothing waits; free is false when it is leased elsewhere.
func (q *Queries) LeaseOldestWaitingEvent(ctx context.Context, arg LeaseOldestWaitingEventParams) (LeaseOldestWaitingEventRow, error) {
	row := q.db.QueryRow(ctx, leaseOldestWaitingEvent,
		arg.Now,
		arg.OrgID,
		arg.DestinationID,
		arg.Due,
		arg.Owner,
		arg.LeaseUntil,
	)
	var i LeaseOldestWaitingEventRow
	err := row.Scan(&i.ID, &i.Free)
	return i, err
}

