const takeTokens = `-- name: TakeTokens :one
WITH clock AS (
    SELECT $1::timestamptz AS now
), want AS (
    SELECT 'destination'::text AS kind, d.id, d.limiter_limit::float8 AS cap,
           d.limiter_limit::float8 / d.limiter_per_seconds::float8 AS rate
    FROM destinations d
    WHERE d.org_id = $2 AND d.id = $3::bigint
    UNION ALL
    SELECT 'connection'::text, c.id, c.limiter_limit::float8, c.limiter_limit::float8 / c.limiter_per_seconds::float8
    FROM connections c
    WHERE c.org_id = $2 AND c.id = $4::bigint
), cur AS (
    SELECT b.subject_kind, b.subject_id, w.rate,
           least(w.cap, b.tokens + extract(epoch FROM (k.now - b.refilled_at))::float8 * w.rate) AS avail
    FROM rate_limit_buckets b
    JOIN want w ON w.kind = b.subject_kind AND w.id = b.subject_id
    CROSS JOIN clock k
    WHERE b.org_id = $2
    ORDER BY b.subject_kind DESC, b.subject_id
    FOR UPDATE OF b
), verdict AS (
    SELECT count(*) = (SELECT count(*) FROM want) AND coalesce(bool_and(avail >= 1), false) AS ok
    FROM cur
), took AS (
    UPDATE rate_limit_buckets b
    SET tokens = c.avail - 1, refilled_at = k.now
    FROM cur c, verdict v, clock k
    WHERE b.org_id = $2 AND b.subject_kind = c.subject_kind AND b.subject_id = c.subject_id AND v.ok
    RETURNING b.subject_id
)
SELECT v.ok::boolean AS taken,
       coalesce((SELECT max(k.now + ((1 - c.avail) / c.rate) * interval '1 second')
                 FROM cur c
                 CROSS JOIN clock k
                 WHERE NOT v.ok AND c.avail < 1),
                '0001-01-01 00:00:00+00')::timestamptz AS due
FROM verdict v
`

type TakeTokensParams struct {
	Now           time.Time
	OrgID         int64
	DestinationID pgtype.Int8
	ConnectionID  pgtype.Int8
}

type TakeTokensRow struct {
	Taken bool
	Due   time.Time
}

// TakeTokens takes one token from each bucket of a Destination and its Connection, or from none: each bucket refills
// at limit / per_seconds up to limit since refilled_at, which may lie in the future after a RetryAfter. It locks the
// buckets in one order, so that two takers never wait for each other. taken says whether the tokens were taken; due is
// when every bucket that has none will hold one, or the zero time.
func (q *Queries) TakeTokens(ctx context.Context, arg TakeTokensParams) (TakeTokensRow, error) {
	row := q.db.QueryRow(ctx, takeTokens,
		arg.Now,
		arg.OrgID,
		arg.DestinationID,
		arg.ConnectionID,
	)
	var i TakeTokensRow
	err := row.Scan(&i.Taken, &i.Due)
	return i, err
}

const tryShareUpdateLock = `-- name: TryShareUpdateLock :one
SELECT pg_try_advisory_xact_lock_shared($1::int, hashint8($2::bigint))::boolean AS free
`

type TryShareUpdateLockParams struct {
	LockClass    int32
	ConnectionID int64
}

// TryShareUpdateLock tries to take, until the transaction ends, the update lock of a Telegram Connection shared,
// without waiting (connections' LockUpdates, class db.TelegramUpdateLockClass, keyed by hashint8 of its id): false
// while an update of the Connection is being handled, such as a press that has not been answered yet. The worker
// tries it after reading the Desired state of an edit of a Telegram Root message, so that the edit a press's Command
// caused never goes out before the press's answer (C-14.FR-5, AC-18), and reschedules the edit instead of waiting.
func (q *Queries) TryShareUpdateLock(ctx context.Context, arg TryShareUpdateLockParams) (bool, error) {
	row := q.db.QueryRow(ctx, tryShareUpdateLock, arg.LockClass, arg.ConnectionID)
	var free bool
	err := row.Scan(&free)
	return free, err
}

