const wakeCopyReplies = `-- name: WakeCopyReplies :execrows
UPDATE thread_replies r
SET next_attempt_at = $1::timestamptz
FROM deliveries d
JOIN destinations ds ON ds.org_id = d.org_id AND ds.id = d.destination_id
WHERE r.org_id = $2 AND d.org_id = $2 AND d.id = r.delivery_id AND ds.type = 'telegram'
  AND ds.connection_id = $3::bigint AND ds.telegram_channel_chat_id = $4::bigint
  AND d.message_id = $5::text AND d.thread_state = 'attached' AND r.state = 'pending'
  AND r.next_attempt_at > $1::timestamptz AND r.last_error_class IS NULL
`

type WakeCopyRepliesParams struct {
	Now           time.Time
	OrgID         int64
	ConnectionID  int64
	ChannelChatID int64
	MessageID     string
}

// WakeCopyReplies makes due at @now the Thread replies that wait, without an error, under the post @message_id of the
// Connection's channel once its Thread is attached, so that they do not wait out telegram.copy_wait.
func (q *Queries) WakeCopyReplies(ctx context.Context, arg WakeCopyRepliesParams) (int64, error) {
	result, err := q.db.Exec(ctx, wakeCopyReplies,
		arg.Now,
		arg.OrgID,
		arg.ConnectionID,
		arg.ChannelChatID,
		arg.MessageID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const wipeDestinationSecrets = `-- name: WipeDestinationSecrets :exec
WITH gone AS (
    SELECT x.id
    FROM destinations x
    WHERE x.org_id = $1 AND ($2::bigint IS NULL OR x.id = $2::bigint)
      AND x.deleted_at IS NOT NULL
      AND (x.signing_secret_ciphertext IS NOT NULL OR x.previous_signing_secret_ciphertext IS NOT NULL
           OR x.proxy_password_ciphertext IS NOT NULL
           OR EXISTS (SELECT 1 FROM destination_secrets n WHERE n.org_id = x.org_id AND n.destination_id = x.id))
      AND NOT EXISTS (SELECT 1
                      FROM deliveries p
                      WHERE p.org_id = x.org_id AND p.destination_id = x.id
                        AND (p.state = 'pending' OR p.lease_until > $3::timestamptz))
      AND NOT EXISTS (SELECT 1
                      FROM webhook_events e
                      WHERE e.org_id = x.org_id AND e.destination_id = x.id AND e.lease_until > $3::timestamptz)
), secrets AS (
    DELETE FROM destination_secrets s
    USING gone
    WHERE s.org_id = $1 AND s.destination_id = gone.id
    RETURNING s.destination_id
)
UPDATE destinations d
SET signing_secret_ciphertext          = NULL,
    signing_secret_key_id              = NULL,
    signing_secret_updated_at          = NULL,
    previous_signing_secret_ciphertext = NULL,
    previous_signing_secret_key_id     = NULL,
    previous_signing_secret_since      = NULL,
    proxy_password_ciphertext          = NULL,
    proxy_password_key_id              = NULL,
    proxy_password_updated_at          = NULL
FROM gone
WHERE d.org_id = $1 AND d.id = gone.id
`

type WipeDestinationSecretsParams struct {
	OrgID int64
	ID    pgtype.Int8
	Now   time.Time
}

// WipeDestinationSecrets wipes the secrets of a deleted Destination once none of its deliveries is pending and no call
// of it — a delivery or an outgoing webhook event — holds a lease at the real time @now, because a call in flight
// still makes its final edit or signs its request with them: the Signing secrets, the proxy password and its named
// Secrets (C-11.FR-14, C-15.FR-12); the delete of the named Secrets runs whether or not the update reads it. It
// changes nothing otherwise, and nothing the second time. @id null wipes every deleted Destination of the
// Organization that qualifies, which the retention of outgoing webhook events runs for a call whose replica stopped.
func (q *Queries) WipeDestinationSecrets(ctx context.Context, arg WipeDestinationSecretsParams) error {
	_, err := q.db.Exec(ctx, wipeDestinationSecrets, arg.OrgID, arg.ID, arg.Now)
	return err
}

const withholdHeldResolved = `-- name: WithholdHeldResolved :many
UPDATE deliveries d
SET held_by_storm_id = NULL, state = 'withheld', updated_at = $1
FROM alert_groups g
WHERE d.org_id = $2 AND d.held_by_storm_id = $3::bigint AND d.state = 'pending' AND g.org_id = $2
  AND g.id = d.alert_group_id AND g.status = 'resolved'
RETURNING g.public_id
`

type WithholdHeldResolvedParams struct {
	Now     time.Time
	OrgID   int64
	StormID int64
}

// WithholdHeldResolved withholds the Alert Groups a Storm held that resolved meanwhile: never published. It returns
// their public_ids, once per delivery, for their alert-group hints.
func (q *Queries) WithholdHeldResolved(ctx context.Context, arg WithholdHeldResolvedParams) ([]string, error) {
	rows, err := q.db.Query(ctx, withholdHeldResolved, arg.Now, arg.OrgID, arg.StormID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []string{}
	for rows.Next() {
		var public_id string
		if err := rows.Scan(&public_id); err != nil {
			return nil, err
		}
		items = append(items, public_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

